'AC-extraction.804.1 AC-testing.seeded-journey.1 AC-testing.must-have.4 AC-extraction.804.2 AC-extraction.804.3 AC-testing.seeded-journey.2 AC-testing.seeded-journey.3'; from __future__ import annotations; from decimal import Decimal; from pathlib import Path; import pytest; from sqlalchemy import select; from sqlalchemy.ext.asyncio import AsyncSession; from src.config import settings; from src.extraction import BankStatementStatus, DocumentSource, UploadedDocument; from src.extraction.extension import transaction_classification; from src.extraction.extension.service import ExtractionService; from src.extraction.extension.statement_posting import auto_create_posted_entries_for_statement; from src.extraction.extension.statement_validation import approve_statement, resolve_statement_transactions; from src.extraction.extension.transaction_classification import CategoryProposal, TransactionCategory; from src.extraction.orm.statement_summary import StatementSummary; from src.identity import User; from src.ledger import Account, AccountType, calculate_account_balance; from tests.statement_ingestion import classify_rows, parse_and_load_statement_projection, posting_dependencies; _sample_dbs_csv = lambda year_month='2026-03': f'Date,Description,Debit Amount,Credit Amount\n{year_month}-05,Salary Revenue,,5000.00\n{year_month}-20,Office Rent,1500.00,\n'.encode()
async def test_statement_upload_csv_direct_parsing(db: AsyncSession, test_user: User) -> None: 'AC-extraction.804.1 AC-testing.must-have.4'; csv_bytes = _sample_dbs_csv('2026-03'); source = DocumentSource.resolve(path=Path('dbs_march_2026.csv'), content=csv_bytes); service = ExtractionService(); result = await service.parse_document(source, institution='DBS', user_id=test_user.id, file_type='csv', db=db); assert result is not None; assert len(result.transactions) == 2; assert result.transactions[0].description == 'Salary Revenue'; assert result.transactions[0].amount == Decimal('5000.00'); assert result.transactions[1].description == 'Office Rent'; assert result.transactions[1].amount == Decimal('1500.00'); statement = (await db.execute(select(StatementSummary).where(StatementSummary.user_id == test_user.id).where(StatementSummary.file_hash == result.source_content_digest))).scalar_one(); assert statement.institution == 'DBS'; assert statement.status == BankStatementStatus.PARSED.value
async def test_statement_list_and_get_details(db: AsyncSession, test_user: User) -> None: 'AC-extraction.804.2'; csv_bytes = _sample_dbs_csv('2026-04'); service = ExtractionService(); source = DocumentSource.resolve(path=Path('dbs_april_2026.csv'), content=csv_bytes); result, statement, transactions = await parse_and_load_statement_projection(service, db=db, user_id=test_user.id, source=source, institution='DBS', file_type='csv'); user_statements = (await db.execute(select(StatementSummary).where(StatementSummary.user_id == test_user.id))).scalars().all(); assert any((s.id == statement.id for s in user_statements)); resolved_txns = await resolve_statement_transactions(db, statement); assert len(resolved_txns) == 2; credit_txn = next((t for t in resolved_txns if 'Salary' in t.description)); debit_txn = next((t for t in resolved_txns if 'Rent' in t.description)); assert credit_txn.amount == Decimal('5000.00'); assert debit_txn.amount == Decimal('1500.00')
