    monkeypatch.setattr(transaction_classification, 'propose_categories', deterministic_proposer); bank = Account(user_id=test_user.id, name='Operating Bank Account', type=AccountType.ASSET, currency='SGD'); db.add(bank); await db.flush(); opening = Decimal('10000.00'); closing = Decimal('13500.00'); csv_bytes = _sample_dbs_csv('2026-05'); service = ExtractionService(); source = DocumentSource.resolve(path=Path('dbs_may_2026.csv'), content=csv_bytes); result, statement, transactions = await parse_and_load_statement_projection(service, db=db, user_id=test_user.id, source=source, institution='DBS', file_type='csv'); statement.account_id = bank.id; statement.currency = bank.currency; statement.period_start = min((t.txn_date for t in transactions)); statement.period_end = max((t.txn_date for t in transactions)); statement.opening_balance = opening; statement.closing_balance = closing
    for t in transactions: t.currency = bank.currency; t.currency_unresolved = False
