async def test_seeded_statement_materializes_without_llm(db: AsyncSession, test_user: User) -> None: 'AC-testing.seeded-journey.1'; csv_bytes = b'Date,Description,Debit Amount,Credit Amount\n2026-06-01,Opening Transfer,,10000.00\n2026-06-15,Client Fee Revenue,,2800.00\n'; source = DocumentSource.resolve(path=Path('seeded_june.csv'), content=csv_bytes); service = ExtractionService(); result, statement, transactions = await parse_and_load_statement_projection(service, db=db, user_id=test_user.id, source=source, institution='Standard Chartered', file_type='csv'); statement.opening_balance = Decimal('10000.00'); statement.closing_balance = Decimal('12800.00'); await db.flush(); persisted = (await db.execute(select(StatementSummary).where(StatementSummary.id == statement.id))).scalar_one(); assert persisted.status == 'parsed'; assert persisted.closing_balance == Decimal('12800.00'); doc = (await db.execute(select(UploadedDocument).where(UploadedDocument.id == persisted.uploaded_document_id))).scalar_one(); assert doc.original_filename == 'seeded_june.csv'; assert len(transactions) == 2
